function findIntegers(n) {
  // Build every valid number from its top bit down: a 0 may always follow, a 1 only after a 0.
  let count = 1;
  const stack = [1];
  while (stack.length > 0) {
    const x = stack.pop();
    if (x > n) continue;
    count++;
    stack.push(x * 2);
    if (x % 2 === 0) stack.push(x * 2 + 1);
  }
  return count;
}

