function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  if (size === 'large') return [1000000000 - pick(1000000)];
  const shape = pick(4);
  // Powers of two and their neighbours sit right on the edges of the bit patterns.
  if (shape === 0) return [Math.max(1, 2 ** (1 + pick(11)) - 1 + pick(3))];
  return [1 + pick(shape === 1 ? 20 : 3000)];
}
